MessageType: enum { GetS, -- request for shared copy GetM, -- request for modified (exclusive) copy PutS, -- evict shared copy PutM, -- evict modified copy (w/ data)
FwdGetS, -- forwarded GetS to owner FwdGetM, -- forwarded GetM to owner Inv, -- invalidation request
Data, -- data response InvAck, -- invalidation acknowledgment PutAck -- put acknowledgment };

